/**
 * Which catalog row an AI item means, and whether we are sure enough to pick it for their (§4.1).
 *
 * The eval's thresholds live in lib/search/thresholds.ts, which is GENERATED by the search eval and
 * never hand-edited. A capture must also clear the conservative floor in
 * lib/capture/auto-resolve-gate.ts (the owner's ruling, 2026-10-17): auto-resolve only at high
 * confidence, otherwise ask. Change the floor there, never here.
 *
 * Pure. No I/O.
 */

import type { PolicyVerdict } from "@/lib/policy/constraints";
import { captureAutoResolves } from "@/lib/capture/auto-resolve-gate";

export type ScoredHit = {
  catalogFoodId: number; revisionId: number; description: string; brand: string | null; score: number;
  /** The verdict catalog search already judged for this hit under the account's rules. */
  policy?: PolicyVerdict;
};

export function pickCandidate(
  hits: ScoredHit[], cls: "branded" | "generic"
): { hit: ScoredHit; autoResolved: boolean } | null {
  if (hits.length === 0) return null;
  return { hit: hits[0], autoResolved: captureAutoResolves(hits, cls) };
}

/** The choices the confirm sheet shows when we did not auto-resolve. */
export function topAlternatives(hits: ScoredHit[], limit = 3): ScoredHit[] {
  return hits.slice(0, limit);
}
